<script setup lang="ts">
import { computed } from 'vue'
import type { Block,Theme } from '../render/types'
import { styleCapability,COLOR_SWATCHES,type BlockStyle } from '../render/blockStyle'
const props=defineProps<{block:Block;theme:Theme;disabled?:boolean}>(),emit=defineEmits<{change:[patch:Partial<BlockStyle>|null];content:[body:Record<string,unknown>];remove:[]}>();const caps=computed(()=>styleCapability(props.block.type));const set=(key:string,value:unknown)=>emit('change',{[key]:value})
function table(action:string){if(props.block.type!=='table')return;const b=props.block;let header=[...b.header],rows=b.rows.map(r=>[...r]);if(action==='addRow')rows.push(header.map(()=>''));if(action==='addCol'){header.push('新列');rows=rows.map(r=>[...r,''])}if(action==='removeRow'&&rows.length>1)rows.pop();if(action==='removeCol'&&header.length>1){header.pop();rows=rows.map(r=>r.slice(0,-1))}emit('content',{type:'table',header,rows})}
</script>
<template><section><h4>选中元素 · {{block.type}}</h4><p v-if="block.locked">手工内容已保护，AI不会覆盖。</p><el-form label-width="86px" :disabled="disabled"><template v-if="caps.text"><el-form-item label="字号（pt）"><el-input-number :model-value="block.style?.size_pt||16" :min="8" :max="72" @change="(v:any)=>set('size_pt',v)"/></el-form-item><el-form-item label="字重"><el-input-number :model-value="block.style?.weight||400" :min="300" :max="900" :step="100" @change="(v:any)=>set('weight',v)"/></el-form-item><el-form-item label="斜体"><el-switch :model-value="!!block.style?.italic" @change="(v:any)=>set('italic',v)"/></el-form-item><el-form-item label="对齐"><el-radio-group :model-value="block.style?.align||'left'" @change="(v:any)=>set('align',v)"><el-radio-button value="left">左</el-radio-button><el-radio-button value="center">中</el-radio-button><el-radio-button value="right">右</el-radio-button></el-radio-group></el-form-item><el-form-item label="文字颜色"><el-select :model-value="block.style?.color||'ink'" @change="(v:any)=>set('color',v)"><el-option v-for="c in COLOR_SWATCHES" :key="c.key" :value="c.key" :label="c.label"/></el-select><el-color-picker :model-value="block.style?.color?.startsWith('#')?block.style.color:theme.palette.ink" @change="(v:any)=>set('color',v)"/></el-form-item></template><template v-if="caps.box"><el-form-item label="填充"><el-select :model-value="block.style?.fill||'none'" @change="(v:any)=>set('fill',v)"><el-option label="无填充" value="none"/><el-option v-for="c in COLOR_SWATCHES" :key="c.key" :value="c.key" :label="c.label"/></el-select><el-color-picker :model-value="block.style?.fill?.startsWith('#')?block.style.fill:theme.palette.surface" @change="(v:any)=>set('fill',v)"/></el-form-item><el-form-item label="圆角"><el-input-number :model-value="block.style?.radius_pt||0" :min="0" :max="48" @change="(v:any)=>set('radius_pt',v)"/></el-form-item><el-form-item label="内边距"><el-input-number :model-value="block.style?.padding_pt||0" :min="0" :max="48" @change="(v:any)=>set('padding_pt',v)"/></el-form-item></template><template v-if="caps.box||caps.borderOnly"><el-form-item label="边框"><el-input-number :model-value="block.style?.border_width_pt||0" :min="0" :max="6" :step=".5" @change="(v:any)=>emit('change',{border_width_pt:v,border_color:block.style?.border_color||'line'})"/></el-form-item><el-form-item label="边框颜色"><el-select :model-value="block.style?.border_color||'line'" @change="(v:any)=>set('border_color',v)"><el-option v-for="c in COLOR_SWATCHES" :key="c.key" :value="c.key" :label="c.label"/></el-select><el-color-picker :model-value="block.style?.border_color?.startsWith('#')?block.style.border_color:theme.palette.line" @change="(v:any)=>set('border_color',v)"/></el-form-item></template><el-button v-if="caps.text||caps.box||caps.borderOnly" @click="emit('change',null)">重置元素样式</el-button><p v-else>图表数据可编辑；元素级样式不受支持。</p><template v-if="block.type==='table'"><div class="table-actions"><el-button @click="table('addRow')">加行</el-button><el-button @click="table('addCol')">加列</el-button><el-button :disabled="block.rows.length<=1" @click="table('removeRow')">删行</el-button><el-button :disabled="block.header.length<=1" @click="table('removeCol')">删列</el-button></div></template></el-form><slot/></section></template>
<style scoped>.el-select{min-width:120px;flex:1}.table-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.table-actions .el-button{margin:0}</style>
